220	class Site:
221	    """One website, driven in its own browser: the active tab, its numbered elements, dialogs, new tabs, downloads."""
222	
223	    def __init__(self, access: dict, context, page, log=print):
224	        self.id = access.get("siteId") or urlparse(access["url"]).hostname
225	        self.url = access["url"]
226	        self.credentials = access.get("credentials") or {}
227	        self.context, self.page, self.log = context, page, log
228	        self.refs: dict[int, object] = {}  # element number -> the frame it is in
229	        self.events: list[str] = []  # dialogs, tabs and downloads since the last view
230	        self.downloads: list[Path] = []
231	        self.full_view, self.shown = "", 0
232	        self.lock = asyncio.Lock()  # one agent at a time drives this browser
233	        context.on("page", self._new_tab)
234	        self._watch(page)
235	
236	    # --- events -------------------------------------------------------------------------------------------------
237	
238	    def _watch(self, page):
239	        page.on("dialog", self._dialog)
240	        page.on("download", self._download)
241	
242	    def _new_tab(self, page):
243	        self._watch(page)
244	        self.page = page
245	        self.events.append("A new tab opened and is now the active tab.")
246	
247	    async def _dialog(self, dialog):
248	        # Browser dialogs block the page until answered. The agents only trigger them on purpose (the final
249	        # confirmation of a bid is one), so they are accepted and reported in the next view.
250	        self.events.append(f"A browser {dialog.type} dialog said {short(dialog.message)!r}; it was accepted.")
251	        try:
252	            await dialog.accept()
253	        except Exception:
254	            pass
255	
256	    async def _download(self, download):
257	        target = Path(tempfile.mkdtemp()) / (download.suggested_filename or "download")
258	        try:
259	            await download.save_as(target)
260	        except Exception as error:
261	            self.events.append(f"A download failed: {short(error)}")
262	            return
263	        self.downloads.append(target)
264	        self.events.append(f"Downloaded {target.name!r}: read it with read_document(download={len(self.downloads)}).")
265	
266	    async def keep_alive(self):
267	        """Loads the current address in the background with this browser's cookies, leaving the page untouched: a
268	        website that logs out after a short idle time keeps the session while its agent waits."""
269	        try:
270	            await self.context.request.get(self.page.url, timeout=8000)
271	        except Exception:
272	            pass
273	
274	    async def fresh_tab(self, url: str | None = None) -> str:
275	        """A new tab in this website's browser (same login), made the active one: away from a page that is stuck."""
276	        page = await self.context.new_page()  # the context's "page" event watches it for dialogs and downloads
277	        self.page = page
278	        return await self.goto(url or self.url)
279	
280	    async def _active(self):
281	        if self.page.is_closed():
282	            open_pages = [page for page in self.context.pages if not page.is_closed()]
283	            self.page = open_pages[-1] if open_pages else await self.context.new_page()
284	            self.events.append("The tab closed; switched to the previous tab.")
285	        return self.page
