380	    async def fill(self, fields: list[dict]) -> str:
381	        """Several inputs at once: text is typed, selects choose the option by label or value, checkboxes take
382	        true/false."""
383	        problems = []
384	        for field in fields:
385	            ref, value = field.get("ref"), field.get("value")
386	            try:
387	                element = self._element(ref)
388	                # a field inside a collapsed section is not editable until the section is open
389	                kind = await element.evaluate("(e) => { for (let d = e.closest('details'); d; d = d.parentElement && "
390	                                              "d.parentElement.closest('details')) d.open = true; "
391	                                              "return e.tagName === 'SELECT' ? 'select' : (e.type || '').toLowerCase(); }",
392	                                              timeout=4000)
393	                if kind == "select":
394	                    try:
395	                        await element.select_option(label=str(value), timeout=3000)
396	                    except Exception:
397	                        await element.select_option(value=str(value), timeout=3000)
398	                elif kind in ("checkbox", "radio"):
399	                    want = value if isinstance(value, bool) else str(value).lower() in ("true", "1", "yes", "ja", "on")
400	                    try:
401	                        await element.set_checked(want, timeout=3000)
402	                    except Exception:
403	                        await element.set_checked(want, force=True, timeout=3000)
404	                else:
405	                    await element.fill(str(value), timeout=4000)
406	            except Exception as error:
407	                problems.append(f"[{ref}]: {short(error, 200)}")
408	        await self._settle()
409	        report = "Filled." if not problems else "Problems: " + "; ".join(problems)
410	        return report + "\n\n" + await self.view()
