439	    async def drag(self, ref, dx: float | None = None, dy: float = 0) -> str:
440	        """Drags an element with the mouse, such as a slider's handle or a range input; without dx, all the way to
441	        the right end of its track."""
442	        element = self._element(ref)
443	        page = await self._active()
444	        await element.scroll_into_view_if_needed(timeout=3000)
445	        box = await element.bounding_box()
446	        if not box:
447	            return "The element is not on screen.\n\n" + await self.view()
448	        track = box
449	        if box["width"] < 60:  # a small handle: its track is the parent
450	            track = await element.evaluate("(e) => { const r = e.parentElement.getBoundingClientRect(); "
451	                                           "return {x: r.x, y: r.y, width: r.width, height: r.height}; }",
452	                                           timeout=4000)
453	        slider = await element.evaluate("(e) => e.type === 'range' ? {min: +e.min || 0, max: +(e.max || 100), "
454	                                        "value: +e.value} : null", timeout=4000)
455	        if slider:
456	            share = (slider["value"] - slider["min"]) / max(1e-9, slider["max"] - slider["min"])
457	            x = box["x"] + 8 + (box["width"] - 16) * share
458	        else:
459	            x = box["x"] + min(10, box["width"] / 2)
460	        y = box["y"] + box["height"] / 2
461	        end_x = x + dx if dx is not None else track["x"] + track["width"] + 30
462	        await page.mouse.move(x, y)
463	        await page.mouse.down()
464	        for step in range(1, 21):
465	            await page.mouse.move(x + (end_x - x) * step / 20, y + dy * step / 20)
466	            await asyncio.sleep(0.02)
467	        await page.mouse.up()
468	        await self._settle()
469	        report = ""
470	        if slider:  # say where the slider ended up, so the model knows whether the drag worked
471	            try:
472	                state = await element.evaluate("(e) => ({value: e.value, max: e.max || '100'})", timeout=2000)
473	                report = f"The slider is now at {state['value']} of {state['max']}.\n\n"
474	            except Exception:
475	                report = "The slider was replaced by the page (it may have unlocked).\n\n"
476	        return report + await self.view()
