559	    async def configure(self, steps: list[dict], apply: str = "") -> str:
560	        """Choices that unlock one another (a configurator): each step selects a value in the field with that label,
561	        then clicks the `apply` button (except after the last step, or where a step says "apply": false) and waits
562	        for the next field to open. Stops at the first step that cannot be done and says why."""
563	        done: list[str] = []
564	        for number, step in enumerate(steps):
565	            field, value = str(step.get("field", "")), str(step.get("value", ""))
566	            frame, found = None, None
567	            for _ in range(12):  # after an apply the next field can take a moment to unlock
568	                frame, found = await self._pick(FIND_SELECT, field)
569	                if found and not found["disabled"]:
570	                    break
571	                await asyncio.sleep(0.5)
572	            so_far = "; ".join(done) or "nothing yet"
573	            if not found:
574	                return f"No selection field labelled {field!r} (chosen so far: {so_far}).\n\n" + await self.view()
575	            if found["disabled"]:
576	                return (f"The field {found['label']!r} is still locked (chosen so far: {so_far}); the choice before "
577	                        "it may need applying.\n\n" + await self.view())
578	            option = choose_option(found["options"], value)
579	            if option is None:
580	                offered = ", ".join(o["text"] for o in found["options"] if o["value"])
581	                return (f"{found['label']!r} offers no {value!r}; it offers: {offered} (chosen so far: {so_far})."
582	                        "\n\n" + await self.view())
583	            await frame.locator('[data-agent-pick="select"]').first.select_option(value=option["value"], timeout=4000)
584	            done.append(f"{found['label']} = {option['text']}")
585	            last = number == len(steps) - 1
586	            if apply and step.get("apply", not last):
587	                button_frame, ok = await self._pick(FIND_BUTTON, apply)
588	                if not ok:
589	                    return f"No button {apply!r} to apply {done[-1]} (chosen so far: {'; '.join(done)}).\n\n" + \
590	                        await self.view()
591	                button = button_frame.locator('[data-agent-pick="button"]').first
592	                try:
593	                    await button.click(timeout=2500)
594	                except Exception:
595	                    await button.evaluate("(e) => e.click()", timeout=3000)
596	                await self._settle()
597	        return "Chosen: " + "; ".join(done) + "\n\n" + await self.view()
