611	    async def read_document(self, ref=None, url: str | None = None, download: int | None = None) -> str:
612	        """The text of a document the model picked: a linked file, a frame's source, or a download."""
613	        if download:
614	            path = self.downloads[int(download) - 1]
615	            return f"Document {path.name}:\n" + extract(path.read_bytes(), path.name)
616	        page = await self._active()
617	        frame = page.main_frame
618	        if ref is not None:
619	            element = self._element(ref)
620	            frame = self.refs[int(ref)]
621	            url = await element.evaluate("(e) => e.href || e.src || e.data || e.getAttribute('href') || ''",
622	                                         timeout=5000)
623	            if not url or url.startswith("javascript"):
624	                # a button that starts a download: click it and read what arrives
625	                before = len(self.downloads)
626	                await self.click(ref)
627	                for _ in range(20):
628	                    if len(self.downloads) > before:
629	                        return await self.read_document(download=len(self.downloads))
630	                    await asyncio.sleep(0.5)
631	                return "The element has no link and clicking it downloaded nothing.\n\n" + await self.view()
632	        if not url:
633	            return "Give the element number, a url, or a download number."
634	        url = urljoin(frame.url, url)
635	        try:
636	            fetched = await frame.evaluate(FETCH, url)
637	        except Exception:
638	            fetched = await page.main_frame.evaluate(FETCH, url)
639	        data = base64.b64decode(fetched["data"])
640	        if "html" in fetched["type"] and "attachment" not in fetched["name"].lower():
641	            # a page's server HTML is not what the browser shows (scripts fill in and change it): open it instead
642	            return f"{url} is a web page, so it was opened in the browser:\n\n" + await self.goto(url)
643	        name = re.sub(r'.*filename\*?=(?:UTF-8\'\')?"?([^";]+)"?.*', r"\1", fetched["name"]) or url
644	        return f"Document {short(name, 120)} (HTTP {fetched['status']}, {fetched['type']}):\n" + extract(data, name, fetched["type"])
