"""One poll of the challenge site; prints one line per change since the last poll (nothing on the first poll but a
baseline line). State and diffs live next to this file."""
import difflib
import hashlib
import json
import re
import subprocess
import sys
import time
import urllib.request
from pathlib import Path

BASE = "https://ehl-challenge.atira.ai"
HERE = Path(__file__).resolve().parent
STATE = HERE / "state"
DIFFS = HERE / "diffs"
ATIRA = str(Path.home() / ".local/bin/atira")
OURS = "Non Deterministic"
DOCS = ["llms.txt", "start.md", "challenges/rfq.md", "docs/cli.md", "docs/api.md", "docs/evals.md",
        "docs/submitting.md", "docs/mcp.md"]


def get(path: str, token: str | None = None) -> str:
    request = urllib.request.Request(f"{BASE}/{path}", headers={"x-api-key": token} if token else {})
    with urllib.request.urlopen(request, timeout=30) as reply:
        return reply.read().decode("utf-8", "replace")


def load(name: str):
    file = STATE / name
    return json.loads(file.read_text()) if file.exists() else None


def save(name: str, value) -> None:
    (STATE / name).write_text(json.dumps(value, indent=1))


def leaderboard(events: list[str]) -> None:
    text = get("challenges/rfq/leaderboard.md")
    rows = {}
    for line in text.splitlines():
        cells = [c.strip() for c in line.strip().strip("|").split("|")]
        if len(cells) >= 9 and cells[0].isdigit():
            team = re.sub(r"\[(.*?)\]\(.*?\)", r"\1", cells[1]).replace("\\_", "_")
            rows[team] = {"rank": int(cells[0]), "quality": cells[4], "cost": cells[5], "time": cells[6],
                          "subs": cells[7]}
    teams = re.search(r"(\d+) teams registered · (\d+) ranked", text)
    before = load("leaderboard.json")
    save("leaderboard.json", rows)
    if before is None:
        events.append(f"BASELINE leaderboard: {len(rows)} ranked, us #{rows.get(OURS, {}).get('rank')}")
        return
    changed = []
    for team, row in rows.items():
        old = before.get(team)
        if old is None:
            changed.append(f"NEW #{row['rank']} {team} q={row['quality']} {row['cost']} {row['time']}")
        elif (old["quality"], old["cost"], old["time"]) != (row["quality"], row["cost"], row["time"]):
            changed.append(f"#{row['rank']} {team} q={row['quality']} {row['cost']} {row['time']} "
                           f"(was q={old['quality']} {old['cost']} {old['time']})")
    if changed:
        events.append("LEADERBOARD: " + "; ".join(changed[:6]) + (f"; +{len(changed) - 6} more" if len(changed) > 6
                                                                 else ""))
    ours, old_ours = rows.get(OURS), before.get(OURS)
    if ours and old_ours and ours["rank"] != old_ours["rank"]:
        events.append(f"OUR RANK: #{ours['rank']} (was #{old_ours['rank']})"
                      + (f" · {teams.group(2)} ranked of {teams.group(1)}" if teams else ""))


def docs(events: list[str]) -> None:
    names = list(DOCS)
    try:
        index = get("llms.txt")
        names += [p for p in re.findall(r"ehl-challenge\.atira\.ai/([\w/.-]+\.md)", index) if p not in names]
    except Exception:
        pass
    hashes = load("docs.json") or {}
    first = not hashes
    for name in names:
        try:
            text = get(name)
        except Exception:
            continue
        text = re.sub(r"as of [^.]*UTC", "", text)
        digest = hashlib.sha256(text.encode()).hexdigest()
        copy = STATE / ("doc-" + name.replace("/", "_"))
        if name in hashes and hashes[name] != digest:
            old = copy.read_text() if copy.exists() else ""
            diff = list(difflib.unified_diff(old.splitlines(), text.splitlines(), name, name, lineterm="", n=1))
            out = DIFFS / f"{name.replace('/', '_')}-{time.strftime('%H%M')}.diff"
            out.write_text("\n".join(diff))
            added = [line[1:].strip() for line in diff if line.startswith("+") and not line.startswith("+++")]
            removed = sum(1 for line in diff if line.startswith("-") and not line.startswith("---"))
            snippet = next((a for a in added if len(a) > 20), added[0] if added else "")[:160]
            events.append(f"DOCS: {name} changed (+{len(added)} -{removed}) {snippet!r} → {out.name}")
        elif name not in hashes and not first:
            events.append(f"DOCS: new page {name}")
        hashes[name] = digest
        copy.write_text(text)
    save("docs.json", hashes)
    if first:
        events.append(f"BASELINE docs: {len(hashes)} pages")


def evals(events: list[str], token: str) -> None:
    listed = json.loads(get("v1/challenges/rfq/evals", token)).get("evals", [])
    seen = load("evals.json")
    now = {}
    for e in listed:
        key = e.get("id") or e.get("slug") or json.dumps(e, sort_keys=True)[:80]
        now[key] = {k: e.get(k) for k in ("slug", "title", "visibility", "team", "team_name", "version",
                                         "current_version", "description") if e.get(k) is not None}
    save("evals.json", now)
    if seen is None:
        events.append(f"BASELINE evals: {len(now)}")
        return
    for key, info in now.items():
        if key not in seen:
            events.append(f"EVAL new: {key} {json.dumps(info, ensure_ascii=False)[:200]}")
        elif info != seen[key]:
            events.append(f"EVAL changed: {key} {json.dumps(info, ensure_ascii=False)[:200]}")


def status(events: list[str]) -> None:
    text = subprocess.run([ATIRA, "status"], capture_output=True, text=True, timeout=60).stdout
    lines = [line.strip() for line in text.splitlines() if re.match(r"\s*(sub|reh)_", line)]
    final = next((line.strip() for line in text.splitlines() if line.startswith("Final private")), "")
    before = load("status.json")
    save("status.json", {"lines": lines, "final": final})
    if before is None:
        return
    for line in lines:
        if line not in before["lines"]:
            events.append(f"OUR RUNS: {re.sub(r'  +', ' ', line)}")
    if final != before["final"]:
        events.append(f"FINAL: {final}")


def main() -> None:
    STATE.mkdir(exist_ok=True)
    DIFFS.mkdir(exist_ok=True)
    events: list[str] = []
    token = subprocess.run([ATIRA, "token"], capture_output=True, text=True, timeout=30).stdout.strip()
    for name, step in (("leaderboard", leaderboard), ("docs", docs), ("evals", lambda e: evals(e, token)),
                       ("status", status)):
        try:
            step(events)
        except Exception as error:  # one failed request must not stop the watch
            print(f"{time.strftime('%H:%M')} poll error in {name}: {error}", file=sys.stderr)
    for event in events:
        print(f"{time.strftime('%H:%M')} {event}", flush=True)


if __name__ == "__main__":
